window.__code__ = window.__code__ || {};
window.__code__["vector-store-py"] = {"code_id": "vector-store-py", "kind": "src", "title": "_vector_store.py", "source_path": "agentscope/src/agentscope/rag/_vdb/_vector_store.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;Abstract base <span class=\"c-kw\">class</span> <span class=\"c-kw\">for</span> vector store backends.</span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">A :<span class=\"c-kw\">class</span>:`VectorStoreBase` instance <span class=\"c-kw\">is</span> the single connection point to</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\">one vector database deployment.  It <span class=\"c-kw\">is</span> created once at application</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\">startup, passed into ``create_app(vector_store=...)``, <span class=\"c-kw\">and</span> shared</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\">across all requests <span class=\"c-kw\">for</span> the lifetime of the process — similar to</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\">:<span class=\"c-kw\">class</span>:`~agentscope.app.storage.StorageBase` <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">:<span class=\"c-kw\">class</span>:`~agentscope.app.message_bus.MessageBus`.</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">Each **knowledge base** maps to one **collection** inside the vector</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">store.  Collections are isolated: different knowledge bases never</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">share a collection, so retrieval <span class=\"c-kw\">is</span> always scoped to a single</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">collection without cross-collection filtering.</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">Lifecycle <span class=\"c-kw\">is</span> managed via the <span class=\"c-kw\">async</span> context manager protocol</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">(``__aenter__`` / ``__aexit__``), which the app lifespan calls</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">automatically.</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\"><span class=\"c-kw\">from</span> abc <span class=\"c-kw\">import</span> ABC, abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> Any, Self</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\"><span class=\"c-kw\">from</span> pydantic <span class=\"c-kw\">import</span> BaseModel, Field</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\"><span class=\"c-kw\">from</span> .._document <span class=\"c-kw\">import</span> Chunk</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\"><span class=\"c-kw\">class</span> VectorRecord(BaseModel):</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;A single record to insert into a vector store collection.</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    Pairs a :<span class=\"c-kw\">class</span>:`Chunk` (the business payload — content, source,</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">    structural metadata) <span class=\"c-kw\">with</span> its dense embedding vector.  ``Chunk``</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">    <span class=\"c-kw\">is</span> intentionally <span class=\"c-kw\">not</span> extended <span class=\"c-kw\">with</span> an ``embedding`` field so its</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">    semantics stay stable across the indexing pipeline; instead the</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    vector lives <span class=\"c-kw\">in</span> this wrapper whose only purpose <span class=\"c-kw\">is</span> &quot;I am about</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    to be inserted into a vector database.&quot;</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">    vector: list[float]</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The dense embedding vector for :attr:`chunk`.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">    document_id: str</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The ID of the source document this record belongs to.</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">    Assigned by the knowledge base layer when the document <span class=\"c-kw\">is</span></span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">    registered.  Backends must persist it at insertion time so that</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">    :meth:`VectorStoreBase.delete` can remove all records of one</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">    document <span class=\"c-kw\">as</span> a unit.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">    chunk: Chunk</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The business payload — content, source, structural metadata.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\"><span class=\"c-kw\">class</span> VectorSearchResult(BaseModel):</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;A single result returned by a similarity search.</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">    Pairs the matched :<span class=\"c-kw\">class</span>:`Chunk` <span class=\"c-kw\">with</span> its similarity score.</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">    ``Chunk`` <span class=\"c-kw\">is</span> intentionally <span class=\"c-kw\">not</span> extended <span class=\"c-kw\">with</span> a ``score`` field so</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">    its semantics stay stable; instead the score lives <span class=\"c-kw\">in</span> this</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">    wrapper whose only purpose <span class=\"c-kw\">is</span> <span class=\"c-str\">&quot;I am a query hit.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">    score: float</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Similarity score.  Higher = more similar <span class=\"c-kw\">for</span> cosine /</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">    dot-product; lower = more similar <span class=\"c-kw\">for</span> L2 distance.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">    document_id: str</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The ID of the source document the matched chunk belongs to —</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">    the same value carried by :attr:`VectorRecord.document_id` at</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">    insertion time.  Lets callers cite, group, <span class=\"c-kw\">or</span> delete the source</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">    document of a hit.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">    chunk: Chunk</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The matched business payload.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\"><span class=\"c-kw\">class</span> DocumentSummary(BaseModel):</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;A lightweight description of one source document inside a collection.</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">    Aggregated by :meth:`VectorStoreBase.list_documents` <span class=\"c-kw\">from</span> the</span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">    records of each ``document_id`` — the vector store <span class=\"c-kw\">is</span> the single</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">    source of truth <span class=\"c-kw\">for</span> <span class=\"c-str\">&quot;what documents exist in a knowledge base&quot;</span>.</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">    document_id: str</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The source document identifier — the same value carried by</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">    :attr:`VectorRecord.document_id` at insertion time.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">    source: str</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The original filename, taken <span class=\"c-kw\">from</span> the first chunk encountered.</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">    All chunks of the same document share the same filename so any</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">    chunk yields the same value.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">    chunk_count: int</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;The total number of chunks indexed for this document.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">    metadata: dict[str, Any] = Field(default_factory=dict)</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Document-level metadata propagated <span class=\"c-kw\">from</span> the parser / uploader</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">    (media type, size, upload time, ...).  Taken <span class=\"c-kw\">from</span> the first chunk</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">    encountered.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\"><span class=\"c-kw\">class</span> VectorStoreBase(ABC):</span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Abstract base <span class=\"c-kw\">class</span> <span class=\"c-kw\">for</span> vector store backends.</span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">    Subclasses implement the concrete connection <span class=\"c-kw\">and</span> query logic <span class=\"c-kw\">for</span> a</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">    specific vector database (Chroma, Milvus, Qdrant, FAISS, etc.).</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">    A single instance <span class=\"c-kw\">is</span> shared across the entire application.  The</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">    underlying client SDK <span class=\"c-kw\">is</span> expected to handle connection pooling <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">    thread safety internally.</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\">    <span class=\"c-com\"># Lifecycle</span></span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> __aenter__(<span class=\"c-kw\">self</span>) -&gt; Self:</span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Enter the <span class=\"c-kw\">async</span> context — open connections <span class=\"c-kw\">if</span> needed.</span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">        The default implementation <span class=\"c-kw\">is</span> a no-op.  Subclasses that need</span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">        explicit connection setup should override this.</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">            `VectorStoreBase`: ``<span class=\"c-kw\">self</span>``.</span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span></span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> __aexit__(</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\">        exc_type: type[BaseException] | <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">        exc_val: BaseException | <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">        exc_tb: Any,</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Exit the <span class=\"c-kw\">async</span> context — close connections <span class=\"c-kw\">if</span> needed.</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">        The default implementation <span class=\"c-kw\">is</span> a no-op.</span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">    <span class=\"c-com\"># Collection management</span></span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> create_collection(</span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">        name: str,</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">        dimensions: int,</span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Create a new collection (vector index).</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">        If the collection already exists, implementations should <span class=\"c-kw\">raise</span></span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">        <span class=\"c-kw\">or</span> silently no-op depending on the backend&<span class=\"c-com\">#x27;s semantics.</span></span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">            name (`str`):</span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">                The collection name. Typically, the knowledge base ID.</span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">            dimensions (`int`):</span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">                The fixed vector dimensionality <span class=\"c-kw\">for</span> this collection.</span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">                All vectors inserted later must have this many elements.</span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> delete_collection(<span class=\"c-kw\">self</span>, name: str) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Delete a collection <span class=\"c-kw\">and</span> all its data.</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">            name (`str`):</span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">                The collection name to delete.</span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> has_collection(<span class=\"c-kw\">self</span>, name: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Check whether a collection exists.</span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">            name (`str`):</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">                The collection name to check.</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">            `bool`: ``<span class=\"c-kw\">True</span>`` <span class=\"c-kw\">if</span> the collection exists.</span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">    <span class=\"c-com\"># Data operations</span></span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> insert(</span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">        collection: str,</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">        records: list[VectorRecord],</span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Insert records into a collection.</span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">            collection (`str`):</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">                The target collection name.</span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">            records (`list[VectorRecord]`):</span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">                The records to insert (each carrying a</span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">                :<span class=\"c-kw\">class</span>:`Chunk` <span class=\"c-kw\">and</span> its embedding vector).</span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> delete(</span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\">        collection: str,</span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\">        document_id: str,</span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"209\"><span class=\"c-no\">209</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Delete all records belonging to one source document.</span></div>\n<div class=\"c-line\" data-line=\"210\"><span class=\"c-no\">210</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"211\"><span class=\"c-no\">211</span><span class=\"c-src\">        Identifies records by the :attr:`VectorRecord.document_id`</span></div>\n<div class=\"c-line\" data-line=\"212\"><span class=\"c-no\">212</span><span class=\"c-src\">        field that backends persist at insertion time.  This matches</span></div>\n<div class=\"c-line\" data-line=\"213\"><span class=\"c-no\">213</span><span class=\"c-src\">        the typical RAG workflow where a user uploads <span class=\"c-kw\">or</span> removes a</span></div>\n<div class=\"c-line\" data-line=\"214\"><span class=\"c-no\">214</span><span class=\"c-src\">        file <span class=\"c-kw\">as</span> a unit.</span></div>\n<div class=\"c-line\" data-line=\"215\"><span class=\"c-no\">215</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"216\"><span class=\"c-no\">216</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"217\"><span class=\"c-no\">217</span><span class=\"c-src\">            collection (`str`):</span></div>\n<div class=\"c-line\" data-line=\"218\"><span class=\"c-no\">218</span><span class=\"c-src\">                The target collection name.</span></div>\n<div class=\"c-line\" data-line=\"219\"><span class=\"c-no\">219</span><span class=\"c-src\">            document_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"220\"><span class=\"c-no\">220</span><span class=\"c-src\">                The source document ID whose records should be</span></div>\n<div class=\"c-line\" data-line=\"221\"><span class=\"c-no\">221</span><span class=\"c-src\">                removed.</span></div>\n<div class=\"c-line\" data-line=\"222\"><span class=\"c-no\">222</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"223\"><span class=\"c-no\">223</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"224\"><span class=\"c-no\">224</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"225\"><span class=\"c-no\">225</span><span class=\"c-src\">    <span class=\"c-com\"># Search</span></span></div>\n<div class=\"c-line\" data-line=\"226\"><span class=\"c-no\">226</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"227\"><span class=\"c-no\">227</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"228\"><span class=\"c-no\">228</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"229\"><span class=\"c-no\">229</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> search(</span></div>\n<div class=\"c-line\" data-line=\"230\"><span class=\"c-no\">230</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"231\"><span class=\"c-no\">231</span><span class=\"c-src\">        collection: str,</span></div>\n<div class=\"c-line\" data-line=\"232\"><span class=\"c-no\">232</span><span class=\"c-src\">        query_vector: list[float],</span></div>\n<div class=\"c-line\" data-line=\"233\"><span class=\"c-no\">233</span><span class=\"c-src\">        top_k: int = 5,</span></div>\n<div class=\"c-line\" data-line=\"234\"><span class=\"c-no\">234</span><span class=\"c-src\">        metadata_filter: dict[str, Any] | <span class=\"c-kw\">None</span> = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"235\"><span class=\"c-no\">235</span><span class=\"c-src\">    ) -&gt; list[VectorSearchResult]:</span></div>\n<div class=\"c-line\" data-line=\"236\"><span class=\"c-no\">236</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Find the most similar records to a query vector.</span></div>\n<div class=\"c-line\" data-line=\"237\"><span class=\"c-no\">237</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"238\"><span class=\"c-no\">238</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"239\"><span class=\"c-no\">239</span><span class=\"c-src\">            collection (`str`):</span></div>\n<div class=\"c-line\" data-line=\"240\"><span class=\"c-no\">240</span><span class=\"c-src\">                The collection to search.</span></div>\n<div class=\"c-line\" data-line=\"241\"><span class=\"c-no\">241</span><span class=\"c-src\">            query_vector (`list[float]`):</span></div>\n<div class=\"c-line\" data-line=\"242\"><span class=\"c-no\">242</span><span class=\"c-src\">                The query embedding vector.</span></div>\n<div class=\"c-line\" data-line=\"243\"><span class=\"c-no\">243</span><span class=\"c-src\">            top_k (`int`, defaults to ``5``):</span></div>\n<div class=\"c-line\" data-line=\"244\"><span class=\"c-no\">244</span><span class=\"c-src\">                Maximum number of results to <span class=\"c-kw\">return</span>.</span></div>\n<div class=\"c-line\" data-line=\"245\"><span class=\"c-no\">245</span><span class=\"c-src\">            metadata_filter (`dict[str, Any] | <span class=\"c-kw\">None</span>`, optional):</span></div>\n<div class=\"c-line\" data-line=\"246\"><span class=\"c-no\">246</span><span class=\"c-src\">                If provided, restrict the search to records whose</span></div>\n<div class=\"c-line\" data-line=\"247\"><span class=\"c-no\">247</span><span class=\"c-src\">                ``chunk.metadata`` matches every ``key == value`` pair</span></div>\n<div class=\"c-line\" data-line=\"248\"><span class=\"c-no\">248</span><span class=\"c-src\">                <span class=\"c-kw\">in</span> this dict.  Backends translate this into a native</span></div>\n<div class=\"c-line\" data-line=\"249\"><span class=\"c-no\">249</span><span class=\"c-src\">                payload filter.  Used <span class=\"c-kw\">for</span> defense-<span class=\"c-kw\">in</span>-depth</span></div>\n<div class=\"c-line\" data-line=\"250\"><span class=\"c-no\">250</span><span class=\"c-src\">                cross-tenant scoping when an isolation strategy</span></div>\n<div class=\"c-line\" data-line=\"251\"><span class=\"c-no\">251</span><span class=\"c-src\">                co-locates multiple knowledge bases inside the same</span></div>\n<div class=\"c-line\" data-line=\"252\"><span class=\"c-no\">252</span><span class=\"c-src\">                collection.</span></div>\n<div class=\"c-line\" data-line=\"253\"><span class=\"c-no\">253</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"254\"><span class=\"c-no\">254</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"255\"><span class=\"c-no\">255</span><span class=\"c-src\">            `list[VectorSearchResult]`:</span></div>\n<div class=\"c-line\" data-line=\"256\"><span class=\"c-no\">256</span><span class=\"c-src\">                Results ordered by descending similarity score.</span></div>\n<div class=\"c-line\" data-line=\"257\"><span class=\"c-no\">257</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"258\"><span class=\"c-no\">258</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"259\"><span class=\"c-no\">259</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"260\"><span class=\"c-no\">260</span><span class=\"c-src\">    <span class=\"c-com\"># Document listing</span></span></div>\n<div class=\"c-line\" data-line=\"261\"><span class=\"c-no\">261</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"262\"><span class=\"c-no\">262</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"263\"><span class=\"c-no\">263</span><span class=\"c-src\">    @abstractmethod</span></div>\n<div class=\"c-line\" data-line=\"264\"><span class=\"c-no\">264</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> list_documents(</span></div>\n<div class=\"c-line\" data-line=\"265\"><span class=\"c-no\">265</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"266\"><span class=\"c-no\">266</span><span class=\"c-src\">        collection: str,</span></div>\n<div class=\"c-line\" data-line=\"267\"><span class=\"c-no\">267</span><span class=\"c-src\">        metadata_filter: dict[str, Any] | <span class=\"c-kw\">None</span> = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"268\"><span class=\"c-no\">268</span><span class=\"c-src\">    ) -&gt; list[DocumentSummary]:</span></div>\n<div class=\"c-line\" data-line=\"269\"><span class=\"c-no\">269</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;List all distinct source documents indexed <span class=\"c-kw\">in</span> a collection.</span></div>\n<div class=\"c-line\" data-line=\"270\"><span class=\"c-no\">270</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"271\"><span class=\"c-no\">271</span><span class=\"c-src\">        Aggregates records by :attr:`VectorRecord.document_id` <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"272\"><span class=\"c-no\">272</span><span class=\"c-src\">        returns one :<span class=\"c-kw\">class</span>:`DocumentSummary` per document.  Backends</span></div>\n<div class=\"c-line\" data-line=\"273\"><span class=\"c-no\">273</span><span class=\"c-src\">        are free to use whatever scrolling / aggregation primitive</span></div>\n<div class=\"c-line\" data-line=\"274\"><span class=\"c-no\">274</span><span class=\"c-src\">        they expose; this method <span class=\"c-kw\">is</span> expected to be O(documents) <span class=\"c-kw\">not</span></span></div>\n<div class=\"c-line\" data-line=\"275\"><span class=\"c-no\">275</span><span class=\"c-src\">        O(chunks) on backends that support payload-only scans.</span></div>\n<div class=\"c-line\" data-line=\"276\"><span class=\"c-no\">276</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"277\"><span class=\"c-no\">277</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"278\"><span class=\"c-no\">278</span><span class=\"c-src\">            collection (`str`):</span></div>\n<div class=\"c-line\" data-line=\"279\"><span class=\"c-no\">279</span><span class=\"c-src\">                The target collection name.</span></div>\n<div class=\"c-line\" data-line=\"280\"><span class=\"c-no\">280</span><span class=\"c-src\">            metadata_filter (`dict[str, Any] | <span class=\"c-kw\">None</span>`, optional):</span></div>\n<div class=\"c-line\" data-line=\"281\"><span class=\"c-no\">281</span><span class=\"c-src\">                If provided, restrict aggregation to records whose</span></div>\n<div class=\"c-line\" data-line=\"282\"><span class=\"c-no\">282</span><span class=\"c-src\">                ``chunk.metadata`` matches every ``key == value`` pair</span></div>\n<div class=\"c-line\" data-line=\"283\"><span class=\"c-no\">283</span><span class=\"c-src\">                <span class=\"c-kw\">in</span> this dict.  Used together <span class=\"c-kw\">with</span> the search-time</span></div>\n<div class=\"c-line\" data-line=\"284\"><span class=\"c-no\">284</span><span class=\"c-src\">                filter when an isolation strategy co-locates multiple</span></div>\n<div class=\"c-line\" data-line=\"285\"><span class=\"c-no\">285</span><span class=\"c-src\">                knowledge bases inside the same collection.</span></div>\n<div class=\"c-line\" data-line=\"286\"><span class=\"c-no\">286</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"287\"><span class=\"c-no\">287</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"288\"><span class=\"c-no\">288</span><span class=\"c-src\">            `list[DocumentSummary]`:</span></div>\n<div class=\"c-line\" data-line=\"289\"><span class=\"c-no\">289</span><span class=\"c-src\">                One summary per distinct ``document_id``, <span class=\"c-kw\">in</span></span></div>\n<div class=\"c-line\" data-line=\"290\"><span class=\"c-no\">290</span><span class=\"c-src\">                unspecified order.</span></div>\n<div class=\"c-line\" data-line=\"291\"><span class=\"c-no\">291</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"292\"><span class=\"c-no\">292</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 292, "explanation": "_vector_store.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [{"title": "RAG", "body": "static（RAGMiddleware 自动检索 HintBlock 一次注入） / agentic（暴露 search_knowledge 工具主动搜）；KnowledgeBase 绑 embedding+vector_store；parser→chunker→embed 入库。"}], "related_docs": ["W08-RAG与多Agent-Team与服务化"]};
